use std::process::Command;
#[link(name="advapi32")]
extern "system" {
 fn OpenProcessToken(process: isize, access: u32, token: *mut isize) -> i32;
 fn GetTokenInformation(token: isize, class: u32, information: *mut u32, size: u32, returned: *mut u32) -> i32;
}
#[link(name="kernel32")]
extern "system" { fn GetCurrentProcess() -> isize; fn CloseHandle(handle: isize) -> i32; }
#[test]
fn native_standard_user_executes_built_binary() {
 let mut token=0isize; let mut elevated=99u32; let mut returned=0u32;
 unsafe {
 assert_ne!(OpenProcessToken(GetCurrentProcess(),8,&mut token),0);
 let ok=GetTokenInformation(token,20,&mut elevated,4,&mut returned);
 CloseHandle(token); assert_ne!(ok,0);
 }
 assert_eq!(elevated,0,"test must run under a native non-elevated token");
 let output=Command::new(env!("CARGO_BIN_EXE_runtime-reuse-fixture")).output().unwrap();
 assert!(output.status.success());
 assert_eq!(String::from_utf8(output.stdout).unwrap().trim(),"FIXTURE-BINARY-EXECUTED");
 println!("NATIVE-TOKEN-ELEVATION=0; COMPILED-BINARY-EXECUTED");
}

